/// <mls fileReference="_102047_/l2/agendaClinica/web/contracts/agenda_diaria.defs.ts" enhancement="_blank"/>

/** Identificação do paciente relacionada à consulta exibida na agenda. */
export interface PacienteIdentificacao {
  details: {
    identification: {
      name: string;
    };
  };
}

/** Paciente resolvido da relação da consulta, nos campos autorizados para o profissional. */
export interface PacienteDaConsulta {
  id: string;
  details: PacienteIdentificacao;
}

/** Identificação do profissional responsável pela consulta. */
export interface ProfissionalIdentificacao {
  details: {
    identification: {
      name: string;
    };
  };
}

/** Profissional resolvido da relação da consulta, nos campos autorizados para a própria agenda. */
export interface ProfissionalDaConsulta {
  id: string;
  details: ProfissionalIdentificacao;
}

/** Detalhes clínicos da consulta necessários para exibir ou registrar o atendimento. */
export interface DetalhesAtendimento {
  details: {
    attendanceNote?: string;
  };
}

/** Payload de detalhes exigido para registrar uma consulta como atendida. */
export interface DetalhesAtendimentoParaRegistro {
  details: {
    attendanceNote: string;
  };
}

/** Linha resumida da agenda diária do profissional. */
export interface ConsultaDoDia {
  id: string;
  pacienteId: string;
  profissionalId: string;
  scheduledAt: string;
  status: 'scheduled' | 'confirmed' | 'noShow' | 'attended';
  paciente: PacienteDaConsulta;
}

/** Consulta aberta pelo profissional, com paciente, profissional e anotação para conferência e registro. */
export interface ConsultaSelecionada {
  id: string;
  version: number;
  pacienteId: string;
  profissionalId: string;
  scheduledAt: string;
  status: 'scheduled' | 'confirmed' | 'noShow' | 'attended';
  paciente: PacienteDaConsulta;
  profissional: ProfissionalDaConsulta;
  details: DetalhesAtendimento;
}

export interface Agenda_diariaContracts {
  /**
   * Finalidade: Carrega a primeira página da agenda de hoje do profissional autenticado para exibir seus horários, pacientes e situações.
   * Entrada: page e pageSize definem a página inicial e a quantidade de consultas por página; ambos vêm do contexto de navegação da agenda.
   * Processamento: Obtém o profissional autenticado no contexto, filtra Consulta por profissionalId desse profissional e por scheduledAt no dia atual, ordena por horário crescente, resolve somente o paciente relacionado e aplica a paginação solicitada. O escopo próprio e os campos retornados respeitam as permissões do profissional.
   * Saída: Retorna consultas no formato de linha da agenda, já limitadas à agenda própria de hoje e acompanhadas de items, page, pageSize e hasMore para a lista paginada.
   */
  'agendaClinica.agenda_diaria.carregarAgendaDiaria': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { consultas: { items: ConsultaDoDia[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['profissional']; grants: ['profissionalConsultarEregistrarPropriaAgenda', 'profissionalIdentificarPacientesDaPropriaAgenda']; scope: 'own' };
  };
  /**
   * Finalidade: Busca sob demanda a próxima página de consultas da agenda de hoje do profissional autenticado.
   * Entrada: page informa a página solicitada pela ação de carregar mais, e pageSize define o limite de linhas dessa página.
   * Processamento: Repete o filtro da agenda própria do dia atual pelo profissional autenticado, ordena as consultas por scheduledAt crescente, resolve o nome do paciente relacionado e aplica a página requerida. Não amplia o escopo para consultas de outro profissional ou de outro dia.
   * Saída: Retorna uma página adicional de linhas da agenda, com items, page, pageSize e hasMore, para ser acrescentada à lista já exibida.
   */
  'agendaClinica.agenda_diaria.carregarMaisConsultasDoDia': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { consultas: { items: ConsultaDoDia[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['profissional']; grants: ['profissionalConsultarEregistrarPropriaAgenda', 'profissionalIdentificarPacientesDaPropriaAgenda']; scope: 'own' };
  };
  /**
   * Finalidade: Abre a consulta escolhida na agenda diária para identificar paciente, horário e profissional e permitir o registro do atendimento.
   * Entrada: consultaId é o identificador da linha selecionada pelo profissional na lista da própria agenda.
   * Processamento: Localiza a Consulta pelo identificador, confirma que ela pertence ao profissional autenticado e que está prevista para o dia atual, resolve os dados autorizados do Paciente e do Profissional relacionados e inclui a versão e a anotação existente.
   * Saída: Retorna a consulta selecionada completa no formato usado pelo resumo, formulário e ações, inclusive version para controle de concorrência no registro.
   */
  'agendaClinica.agenda_diaria.carregarConsultaSelecionada': {
    kind: 'qry';
    input: { consultaId: string };
    output: { consulta: ConsultaSelecionada };
    rules: [];
    access: { actors: ['profissional']; grants: ['profissionalConsultarEregistrarPropriaAgenda', 'profissionalIdentificarPacientesDaPropriaAgenda']; scope: 'own' };
  };
  /**
   * Finalidade: Registra o atendimento realizado na consulta aberta pelo profissional e devolve o estado atualizado para redesenhar a página.
   * Entrada: id e version identificam a Consulta e protegem a alteração concorrente; details.attendanceNote é a anotação obrigatória enviada pelo formulário para o payload da transição.
   * Processamento: Confirma que a consulta pertence ao profissional autenticado e executa Consulta.registrarAtendimento. Aplica transicaoConsultaValida, aceitando somente a mudança de scheduled ou confirmed para attended, e anotacaoObrigatoriaNoAtendimento, recusando payload sem anotação. Após a transição, resolve paciente e profissional relacionados para compor o registro atualizado.
   * Saída: Retorna a consulta já atendida, com nova version, status e anotação persistida, para atualizar tanto o detalhe aberto quanto sua linha na agenda sem uma segunda chamada.
   */
  'agendaClinica.agenda_diaria.registrarAtendimento': {
    kind: 'cmd';
    writes: 'Consulta.registrarAtendimento';
    input: { id: string; version: number; details: DetalhesAtendimentoParaRegistro };
    output: { consulta: ConsultaSelecionada };
    rules: ['transicaoConsultaValida', 'anotacaoObrigatoriaNoAtendimento'];
    access: { actors: ['profissional']; grants: ['profissionalConsultarEregistrarPropriaAgenda', 'profissionalIdentificarPacientesDaPropriaAgenda']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/agendaClinica/web/contracts/consultas.defs.ts" enhancement="_blank"/>

/** Cabeçalho da agenda no dia consultado. */
export interface AgendaCabecalho {
  dataAgenda: string;
}

/** Identificação do paciente exibida e usada na localização. */
export interface PacienteIdentificacao {
  details: {
    identification: {
      readonly subtype: 'Person';
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      docType?: 'SSN' | 'EIN' | 'Passport' | 'DriversLicense' | 'NationalId' | 'CPF' | 'CNPJ' | 'VAT' | 'Other';
      docId?: string;
    };
  };
}

/** Canais de contato derivados do paciente, preservados como a estrutura mestre autorizada para conferência. */
export interface ContatosPaciente {
  details: {
    base: {
      readonly contacts: string;
    };
  };
}

/** Dados-base do paciente necessários à conferência da consulta. */
export interface PacienteBase {
  details: {
    base: string;
  };
  contacts: ContatosPaciente;
}

/** Paciente identificado em uma linha de agenda ou opção de agendamento. */
export interface PacienteResumo {
  id: string;
  identification: PacienteIdentificacao;
}

/** Paciente vinculado à consulta, com identificação e contatos para conferência. */
export interface PacienteDetalhe {
  id: string;
  identification: PacienteIdentificacao;
  base: PacienteBase;
}

/** Identificação do profissional exibida na agenda e na escolha do agendamento. */
export interface ProfissionalIdentificacao {
  details: {
    identification: {
      readonly subtype: 'Person';
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      docType?: 'CPF' | 'Passport' | 'NationalId' | 'Other';
      docId?: string;
      countryCode: string;
    };
  };
}

/** Dados da agenda clínica que qualificam o profissional escolhido. */
export interface AgendaClinicaProfissional {
  details: {
    agendaClinica: {
      professionalType: 'medical' | 'therapist';
    };
  };
}

/** Profissional identificado em uma linha de agenda ou opção de agendamento. */
export interface ProfissionalResumo {
  id: string;
  identification: ProfissionalIdentificacao;
  agendaClinica: AgendaClinicaProfissional;
}

/** Linha pronta para a agenda, com os nomes resolvidos do paciente e do profissional. */
export interface ConsultaAgenda {
  id: string;
  pacienteId: string;
  profissionalId: string;
  scheduledAt: string;
  status: 'scheduled' | 'confirmed' | 'noShow' | 'attended';
  paciente: PacienteResumo;
  profissional: ProfissionalResumo;
}

/** Consulta selecionada, composta com paciente e profissional, para conferência, ações e preenchimento do formulário. */
export interface ConsultaDetalhe {
  id: string;
  version: number;
  pacienteId: string;
  profissionalId: string;
  scheduledAt: string;
  status: 'scheduled' | 'confirmed' | 'noShow' | 'attended';
  paciente: PacienteDetalhe;
  profissional: ProfissionalResumo;
}

export interface ConsultasContracts {
  /**
   * Finalidade: Carrega a visão inicial da agenda clínica para a recepcionista localizar e conferir consultas.
   * Entrada: Recebe a data de agenda do contexto, um filtro opcional de situação e a página solicitada.
   * Processamento: Busca consultas da data informada, aplica a situação quando ela foi escolhida, ordena por data e horário e resolve os dados mestres permitidos de paciente e profissional. Calcula quantidadePendentes a partir das consultas da data com situação scheduled ou confirmed; o indicador é derivado e não é gravado.
   * Saída: Devolve o cabeçalho da data, o indicador já calculado e uma página de linhas de agenda prontas para exibição.
   */
  'agendaClinica.consultas.carregarAgenda': {
    kind: 'qry';
    input: { dataAgenda: string; status?: 'scheduled' | 'confirmed' | 'noShow' | 'attended'; page: number; pageSize: number };
    output: { cabecalho: AgendaCabecalho; readonly quantidadePendentes: number; agenda: { items: ConsultaAgenda[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Substitui a agenda exibida quando a recepcionista muda a data ou a situação procurada.
   * Entrada: Recebe a data, a situação opcional e a primeira página desejada para a nova consulta de agenda.
   * Processamento: Aplica os filtros informados, ordena a agenda por horário, compõe nomes e tipo de profissional e calcula novamente quantidadePendentes para a data escolhida.
   * Saída: Devolve o novo cabeçalho, indicador e página filtrada, para substituir a visão anterior sem a página somar registros.
   */
  'agendaClinica.consultas.filtrarAgenda': {
    kind: 'qry';
    input: { dataAgenda: string; status?: 'scheduled' | 'confirmed' | 'noShow' | 'attended'; page: number; pageSize: number };
    output: { cabecalho: AgendaCabecalho; readonly quantidadePendentes: number; agenda: { items: ConsultaAgenda[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Traz a próxima página da mesma agenda já filtrada.
   * Entrada: Recebe os filtros atuais e o número da próxima página com seu tamanho.
   * Processamento: Repete exatamente os filtros de data e situação da agenda atual, mantém a ordenação por horário e busca apenas a página solicitada.
   * Saída: Devolve mais linhas de agenda e os metadados de paginação para acrescentá-las à lista existente.
   */
  'agendaClinica.consultas.carregarMaisAgenda': {
    kind: 'qry';
    input: { dataAgenda: string; status?: 'scheduled' | 'confirmed' | 'noShow' | 'attended'; page: number; pageSize: number };
    output: { agenda: { items: ConsultaAgenda[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega a consulta escolhida com os dados necessários para conferir, agir ou reutilizar no formulário.
   * Entrada: Recebe o identificador da linha selecionada na agenda.
   * Processamento: Lê a consulta por id e compõe o paciente com identificação e contatos, além do profissional com identificação e tipo de atuação.
   * Saída: Devolve uma consulta detalhada com versão, para exibir o contexto conferido e enviar transições com concorrência otimista.
   */
  'agendaClinica.consultas.consultarConsultaSelecionada': {
    kind: 'qry';
    input: { id: string };
    output: { consulta: ConsultaDetalhe };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Localiza pacientes para a recepcionista escolher quem receberá o novo agendamento.
   * Entrada: Recebe o texto informado no nome do paciente e a primeira página de resultados.
   * Processamento: Pesquisa o índice de nomes de pacientes dentro da organização e retorna somente a identificação que a recepcionista pode consultar.
   * Saída: Devolve uma página de pacientes identificados para preencher pacienteId no formulário de agendamento.
   */
  'agendaClinica.consultas.localizarPacientesParaAgendamento': {
    kind: 'qry';
    input: { termo: string; page: number; pageSize: number };
    output: { pacientes: { items: PacienteResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Acrescenta resultados à localização de pacientes usada no agendamento.
   * Entrada: Recebe o mesmo termo de nome e a próxima página solicitada.
   * Processamento: Mantém a pesquisa de pacientes pelo nome e busca somente a próxima página de registros permitidos.
   * Saída: Devolve mais opções de paciente e metadados de paginação para anexar à pesquisa atual.
   */
  'agendaClinica.consultas.carregarMaisPacientesParaAgendamento': {
    kind: 'qry';
    input: { termo: string; page: number; pageSize: number };
    output: { pacientes: { items: PacienteResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Localiza profissionais da agenda para a recepcionista definir o responsável pela nova consulta.
   * Entrada: Recebe o nome pesquisado e a primeira página de resultados.
   * Processamento: Pesquisa profissionais da organização pelo nome e compõe sua identificação e o tipo de atuação da agenda clínica.
   * Saída: Devolve uma página de profissionais que o formulário usa para preencher profissionalId.
   */
  'agendaClinica.consultas.localizarProfissionaisParaAgendamento': {
    kind: 'qry';
    input: { termo: string; page: number; pageSize: number };
    output: { profissionais: { items: ProfissionalResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Acrescenta resultados à localização de profissionais para o agendamento.
   * Entrada: Recebe o termo de nome mantido na pesquisa e a próxima página.
   * Processamento: Repete a busca de profissionais pelo nome e retorna apenas a página posterior solicitada.
   * Saída: Devolve opções adicionais de profissional para anexar à lista de escolha existente.
   */
  'agendaClinica.consultas.carregarMaisProfissionaisParaAgendamento': {
    kind: 'qry';
    input: { termo: string; page: number; pageSize: number };
    output: { profissionais: { items: ProfissionalResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Cria o agendamento informado pela recepcionista e devolve a visão que a página precisa redesenhar.
   * Entrada: Recebe pacienteId, profissionalId e data e horário editados no formulário, além dos filtros e da página de agenda atualmente visíveis.
   * Processamento: Cria a consulta com situação scheduled e aplica consultaSemConflito, recusando o comando se já existir consulta do mesmo profissional na mesma data e horário. Em seguida compõe a consulta criada e recompõe a página atual da agenda e seu indicador derivado.
   * Saída: Devolve a consulta criada com versão e vínculos resolvidos, bem como cabeçalho, indicador e página de agenda atualizados; não exige nova chamada para redesenhar a página.
   */
  'agendaClinica.consultas.agendarConsulta': {
    kind: 'cmd';
    writes: 'Consulta.create';
    input: { pacienteId: string; profissionalId: string; scheduledAt: string; dataAgenda: string; statusAgenda?: 'scheduled' | 'confirmed' | 'noShow' | 'attended'; page: number; pageSize: number };
    output: { consulta: ConsultaDetalhe; cabecalho: AgendaCabecalho; readonly quantidadePendentes: number; agenda: { items: ConsultaAgenda[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['consultaSemConflito'];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Registra a confirmação telefônica da consulta conferida e atualiza a agenda exibida.
   * Entrada: Recebe id e version da consulta selecionada, mais os filtros e a página de agenda que precisam ser redesenhados.
   * Processamento: Executa a transição confirmarConsulta e aplica transicaoConsultaValida, aceitando somente a mudança de scheduled para confirmed. Após a transição, recompõe a consulta, a página filtrada e quantidadePendentes.
   * Saída: Devolve a consulta confirmada com a nova versão, o indicador recalculado e as linhas atualizadas da página da agenda.
   */
  'agendaClinica.consultas.confirmarConsulta': {
    kind: 'cmd';
    writes: 'Consulta.confirmarConsulta';
    input: { id: string; version: number; dataAgenda: string; statusAgenda?: 'scheduled' | 'confirmed' | 'noShow' | 'attended'; page: number; pageSize: number };
    output: { consulta: ConsultaDetalhe; cabecalho: AgendaCabecalho; readonly quantidadePendentes: number; agenda: { items: ConsultaAgenda[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['transicaoConsultaValida'];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Registra a falta do paciente na consulta conferida e devolve a agenda já atualizada.
   * Entrada: Recebe id e version da consulta, junto dos filtros e da página de agenda em uso.
   * Processamento: Executa registrarFalta conforme transicaoConsultaValida, permitindo somente scheduled ou confirmed para noShow. Recompõe a consulta resultante, a página filtrada e o indicador derivado após a transição.
   * Saída: Devolve a consulta marcada como falta, com nova versão, e os dados completos para redesenhar o cabeçalho, o indicador e a lista sem recarga adicional.
   */
  'agendaClinica.consultas.registrarFalta': {
    kind: 'cmd';
    writes: 'Consulta.registrarFalta';
    input: { id: string; version: number; dataAgenda: string; statusAgenda?: 'scheduled' | 'confirmed' | 'noShow' | 'attended'; page: number; pageSize: number };
    output: { consulta: ConsultaDetalhe; cabecalho: AgendaCabecalho; readonly quantidadePendentes: number; agenda: { items: ConsultaAgenda[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['transicaoConsultaValida'];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas', 'recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/agendaClinica/web/contracts/pacientes.defs.ts" enhancement="_blank"/>

/** Identificação resumida exibida em cada resultado da busca de pacientes. */
export interface PatientListIdentification {
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      docId?: string;
    };
  };
}

/** Dados do paciente necessários para localizar e distinguir resultados pelo nome. */
export interface PatientListDetails {
  identification: PatientListIdentification;
}

/** Paciente em formato compacto para a lista de localização. */
export interface PatientListItem {
  id: string;
  details: PatientListDetails;
}

/** Identificação completa do paciente para conferência e após o cadastro. */
export interface PatientIdentification {
  details: {
    identification: {
      readonly subtype: 'Person';
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      docType?: 'SSN' | 'EIN' | 'Passport' | 'DriversLicense' | 'NationalId' | 'CPF' | 'CNPJ' | 'VAT' | 'Other';
      docId?: string;
    };
  };
}

/** Bloco base do paciente autorizado para conferência na ficha. */
export interface PatientBase {
  details: {
    base: string;
  };
}

/** Dados completos que a página mostra ao conferir o paciente. */
export interface PatientDetails {
  identification: PatientIdentification;
  base: PatientBase;
}

/** Paciente selecionado, pronto para conferência e continuidade no agendamento. */
export interface PatientDetail {
  id: string;
  details: PatientDetails;
}

export interface PacientesContracts {
  /**
   * Finalidade: Inicializa a área de localização de pacientes sem trazer cadastros antes de a recepcionista informar um nome.
   * Entrada: page e pageSize definem a primeira janela da lista. Como a página abriu sem critério de nome, não há termo de busca.
   * Processamento: Prepara a lista paginada em estado vazio quando não há busca nominal. Não consulta nem transfere todos os pacientes; a localização é feita sob demanda por searchPatients.
   * Saída: Retorna patients no contrato paginado para alimentar a lista em estado inicial, preservando a mesma estrutura usada pela busca.
   */
  'agendaClinica.pacientes.loadPatients': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { patients: { items: PatientListItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas']; scope: 'organization' };
  };
  /**
   * Finalidade: Localiza pacientes pelo nome para a recepcionista escolher quem seguirá para o agendamento.
   * Entrada: nameSearch é o nome informado pela recepcionista; page e pageSize definem a janela solicitada dos resultados.
   * Processamento: Pesquisa Paciente pelo índice de nome, aplica o termo informado e retorna somente a página solicitada. Compõe cada resultado com identificador, nome, situação e número de documento, sem carregar a ficha completa.
   * Saída: Retorna patients paginado, já no formato compacto que a lista apresenta para identificar e selecionar um paciente.
   */
  'agendaClinica.pacientes.searchPatients': {
    kind: 'qry';
    input: { nameSearch: string; page: number; pageSize: number };
    output: { patients: { items: PatientListItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega a ficha do paciente que a recepcionista selecionou para confirmar sua identificação antes de ir ao agendamento.
   * Entrada: patientId é o identificador do resultado escolhido na lista.
   * Processamento: Lê o paciente selecionado e compõe sua identificação completa e seu bloco base autorizado. A situação é devolvida como campo derivado do cadastro mestre, sem ser gravada por esta consulta.
   * Saída: Retorna patient para a ficha de conferência, evitando carregar dados completos de todos os itens da lista.
   */
  'agendaClinica.pacientes.loadPatientDetail': {
    kind: 'qry';
    input: { patientId: string };
    output: { patient: PatientDetail };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas']; scope: 'organization' };
  };
  /**
   * Finalidade: Cadastra ou associa o novo paciente informado pela recepcionista e o deixa imediatamente disponível para conferência e agendamento.
   * Entrada: name é o nome obrigatório de identificação; docType e docId são o tipo e o número do documento quando informados no formulário.
   * Processamento: Executa Paciente.create por meio do cadastro mestre createOrAttach: valida o formato do documento quando ele for informado, procura identidade existente pelo documento e cria ou associa o papel de paciente conforme necessário. A situação, o subtipo e os dados base retornados são determinados pelo cadastro mestre; não são recebidos como campos graváveis da página.
   * Saída: Retorna a ficha completa do paciente cadastrado e sua projeção compacta para atualizar a ficha e inserir ou atualizar o resultado correspondente na lista sem uma segunda chamada.
   */
  'agendaClinica.pacientes.savePatient': {
    kind: 'cmd';
    writes: 'Paciente.create';
    input: { details: { identification: { name: string; docType?: 'SSN' | 'EIN' | 'Passport' | 'DriversLicense' | 'NationalId' | 'CPF' | 'CNPJ' | 'VAT' | 'Other'; docId?: string } } };
    output: { patient: PatientDetail; patientListItem: PatientListItem };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaGerenciarPacientesEconsultas']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/agendaClinica/web/contracts/profissionais.defs.ts" enhancement="_blank"/>

/** Identificação resumida exibida na lista de profissionais disponíveis. */
export interface ProfessionalDirectoryIdentification {
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
  };
}

/** Dados resumidos da agenda clínica exibidos na lista. */
export interface ProfessionalDirectoryAgendaClinica {
  details: {
    agendaClinica: {
      professionalType: 'medical' | 'therapist';
    };
  };
}

/** Agrupa os dados do profissional necessários para localizar um cadastro na lista. */
export interface ProfessionalDirectoryDetails {
  identification: ProfessionalDirectoryIdentification;
  agendaClinica: ProfessionalDirectoryAgendaClinica;
}

/** Linha paginada do diretório de profissionais disponíveis. */
export interface ProfessionalDirectoryItem {
  id: string;
  details: ProfessionalDirectoryDetails;
}

/** Dados de identificação completos usados para conferir e manter o cadastro. */
export interface ProfessionalIdentification {
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      docType?: 'CPF' | 'Passport' | 'NationalId' | 'Other';
      docId?: string;
      countryCode: string;
    };
  };
}

/** Dados da agenda clínica que definem a atuação do profissional. */
export interface ProfessionalAgendaClinica {
  details: {
    agendaClinica: {
      professionalType: 'medical' | 'therapist';
    };
  };
}

/** Agrupa os dados completos de identificação e atuação do profissional. */
export interface ProfessionalDetails {
  identification: ProfessionalIdentification;
  agendaClinica: ProfessionalAgendaClinica;
}

/** Cadastro completo do profissional selecionado ou recém-gravado. */
export interface ProfessionalRecord {
  id: string;
  version: number;
  details: ProfessionalDetails;
}

export interface ProfissionaisContracts {
  /**
   * Finalidade: Carrega a primeira página do diretório de profissionais disponíveis quando a página é aberta.
   * Entrada: page e pageSize definem a página inicial e a quantidade de linhas adequadas à tela; são parâmetros de navegação do estado da página.
   * Processamento: Lista somente profissionais da organização cuja situação do cadastro mestre é Active, pois a página prioriza quem está disponível para o agendamento. Ordena de forma estável pelo nome e projeta apenas identificador, nome, situação e tipo de atuação.
   * Saída: Retorna professionals no contrato paginado { items, page, pageSize, hasMore }, já filtrado para profissionais ativos, para preencher o diretório sem carregar documentos ou o cadastro completo.
   */
  'agendaClinica.profissionais.loadAvailableProfessionals': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { professionals: { items: ProfessionalDirectoryItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Obtém a próxima página do diretório de profissionais disponíveis quando a recepcionista solicita mais resultados.
   * Entrada: page é a página seguinte solicitada e pageSize é a quantidade de linhas por página; ambos vêm do estado de paginação da lista.
   * Processamento: Aplica o mesmo recorte organizacional, situação Active e ordenação estável do carregamento inicial, buscando somente a página solicitada.
   * Saída: Retorna professionals no contrato paginado para anexar seus items ao diretório já mostrado e informar se ainda há mais resultados.
   */
  'agendaClinica.profissionais.loadMoreAvailableProfessionals': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { professionals: { items: ProfessionalDirectoryItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Localiza, sob demanda, profissionais disponíveis pelo nome para a recepcionista escolher o cadastro certo.
   * Entrada: search é o texto de nome informado pela recepcionista; page e pageSize controlam a primeira página da busca.
   * Processamento: Usa a capacidade de localização por nome no escopo da organização, mantém somente registros Active e aplica correspondência normalizada por nome. Ordena os resultados de forma estável e não expõe documento nesta consulta resumida.
   * Saída: Retorna professionals no contrato paginado, substituindo a lista corrente pelos resultados da busca já adequados à seleção.
   */
  'agendaClinica.profissionais.searchAvailableProfessionals': {
    kind: 'qry';
    input: { search: string; page: number; pageSize: number };
    output: { professionals: { items: ProfessionalDirectoryItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Busca a próxima página da localização por nome sem reiniciar os resultados já exibidos.
   * Entrada: search preserva o termo de busca ativo; page e pageSize identificam a próxima página a carregar.
   * Processamento: Repete exatamente o recorte organizacional, a situação Active, a normalização de nome e a ordenação estável da busca inicial, limitando a leitura à página solicitada.
   * Saída: Retorna professionals no contrato paginado para acrescentar os novos items aos resultados de busca existentes.
   */
  'agendaClinica.profissionais.loadMoreProfessionalSearch': {
    kind: 'qry';
    input: { search: string; page: number; pageSize: number };
    output: { professionals: { items: ProfessionalDirectoryItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega o cadastro completo do profissional que a recepcionista selecionou para conferência e edição.
   * Entrada: id é o identificador do profissional selecionado no diretório.
   * Processamento: Lê o registro pelo identificador dentro do escopo organizacional autorizado e compõe nome, documento, país, situação, tipo de atuação e version para controle otimista. Não carrega dados de privacidade ou dados gerais que a página não usa.
   * Saída: Retorna professional completo para preencher simultaneamente o detalhe e o formulário de manutenção.
   */
  'agendaClinica.profissionais.getProfessional': {
    kind: 'qry';
    input: { id: string };
    output: { professional: ProfessionalRecord };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Cria ou reutiliza e vincula o cadastro mestre de uma pessoa como profissional da agenda clínica.
   * Entrada: name, docType, docId e countryCode preenchem a identificação mestre; professionalType grava a atuação medical ou therapist no namespace agendaClinica.
   * Processamento: Executa register.createOrAttach no escopo autorizado. Valida a combinação de documento e país exigida pela operação e mantém a identificação no cadastro mestre, gravando no namespace agendaClinica somente a atuação permitida.
   * Saída: Retorna professional com id e version gerados ou resolvidos, situação, identificação e atuação para redesenhar detalhe e formulário e inserir ou atualizar a linha correspondente no diretório.
   */
  'agendaClinica.profissionais.createProfessional': {
    kind: 'cmd';
    writes: 'Profissional.create';
    input: { details: { identification: { name: string; docType?: 'CPF' | 'Passport' | 'NationalId' | 'Other'; docId?: string; countryCode: string }; agendaClinica: { professionalType: 'medical' | 'therapist' } } };
    output: { professional: ProfessionalRecord };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
  /**
   * Finalidade: Atualiza os dados de identificação permitidos e o tipo de atuação do profissional selecionado.
   * Entrada: id identifica o cadastro e version faz a concorrência otimista; os demais campos são as alterações de nome, documento, país e tipo de atuação preenchidas no formulário.
   * Processamento: Recusa versão desatualizada e aplica edit.platformFields à identificação e edit.moduleNamespace exclusivamente a agendaClinica.professionalType. Não altera situação, consentimento ou dados gerais.
   * Saída: Retorna professional com a nova version e todos os dados exibidos, permitindo redesenhar detalhe e formulário e atualizar a linha da lista sem nova leitura.
   */
  'agendaClinica.profissionais.updateProfessional': {
    kind: 'cmd';
    writes: 'Profissional.update';
    input: { id: string; version: number; details: { identification: { name: string; docType?: 'CPF' | 'Passport' | 'NationalId' | 'Other'; docId?: string; countryCode: string }; agendaClinica: { professionalType: 'medical' | 'therapist' } } };
    output: { professional: ProfessionalRecord };
    rules: [];
    access: { actors: ['recepcionista']; grants: ['recepcionistaConsultarProfissionais']; scope: 'organization' };
  };
}

